1	import { NextRequest, NextResponse } from "next/server";
2	import { stripe, stripeConfigured } from "@/lib/stripe";
3	import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";
4	import { releaseReservation } from "@/lib/promo-redemption";
5	import { releaseOrderCouponReservation } from "@/lib/coupon-redemption";
6	import { handleFailedPaymentIntent } from "@/lib/payment-failed-recovery";
7	import type Stripe from "stripe";
8	
9	export async function POST(req: NextRequest) {
10	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
11	    return NextResponse.json({ error: "not configured" }, { status: 400 });
12	  }
13	  const sig = req.headers.get("stripe-signature");
14	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
15	  const raw = await req.text();
16	
17	  let event;
18	  try {
19	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
20	  } catch {
21	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
22	  }
23	
24	  if (event.type === "checkout.session.completed") {
25	    const session = event.data.object as { id: string };
26	    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
27	    // throw the result away, which meant the webhook credited the wallet and then
28	    // — by winning the race — caused the success-redirect to see `credited: false`
29	    // and skip provisioning entirely. The webhook is the reliable signal (the
30	    // redirect may never happen at all), so it must be able to fulfil on its own.
31	    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
32	    // two callers racing is safe: exactly one does the work.
33	    //
34	    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
35	    // event, and the failure is already recorded on the FulfilledSession row and
36	    // surfaced to the customer.
37	    try {
38	      await fulfilCheckoutSession(session.id);
39	    } catch (e) {
40	      console.error("[stripe-webhook] fulfil failed", session.id, e);
41	    }
42	  }
43	
44	  // A checkout the customer never completed: Stripe expires it (we cap the payable
45	  // window at ORDER_CHECKOUT_EXPIRES_MS). RELEASE any first-month-free hold it carried
46	  // so the customer's one-time offer is returned promptly rather than waiting for the
47	  // worker sweep. Guarded to RESERVED, so a completed+confirmed grant is never revoked.
48	  // (If this event type isn't enabled in the Stripe dashboard, the worker sweep is the
49	  // backstop — the hold's reservedUntil has passed by the time the session expires.)
50	  if (event.type === "checkout.session.expired") {
51	    const session = event.data.object as Stripe.Checkout.Session;
52	    const token = session.metadata?.nxeonPromoReservation;
53	    if (token) {
54	      try {
55	        await releaseReservation(token);
56	      } catch (e) {
57	        console.error("[stripe-webhook] release reservation failed", token, e);
58	      }
59	    }
60	    // Same for a checkout-coupon hold — return its per-person slot AND its global-cap
61	    // slot (timesRedeemed decrement inside releaseOrderCouponReservation). Guarded to
62	    // RESERVED, so a completed+confirmed CONSUMED redemption is never revoked.
63	    const couponToken = session.metadata?.nxeonCouponReservation;
64	    if (couponToken) {
65	      try {
66	        await releaseOrderCouponReservation(couponToken);
67	      } catch (e) {
68	        console.error("[stripe-webhook] release coupon reservation failed", couponToken, e);
69	      }
70	    }
71	  }
72	
73	  // A payment attempt failed. Filtered inside handleFailedPaymentIntent to only
74	  // act on the 3D Secure / authentication-stalled case — ordinary declines are
75	  // already shown to the customer inline by Stripe's own checkout UI. Errors
76	  // swallowed deliberately: a recovery-email hiccup must never surface as a
77	  // webhook failure Stripe would retry indefinitely.
78	  if (event.type === "payment_intent.payment_failed") {
79	    const pi = event.data.object as Stripe.PaymentIntent;
80	    try {
81	      await handleFailedPaymentIntent(pi);
82	    } catch (e) {
83	      console.error("[stripe-webhook] failed-payment recovery failed", pi.id, e);
84	    }
85	  }
86	
87	  return NextResponse.json({ received: true });
88	}
