6	/**
7	 * The ONLY fulfilment trigger for Coinbase Commerce — unlike Stripe and PayPal,
8	 * there is no client-driven "capture" step to race: a crypto payment is confirmed
9	 * entirely off our page, on-chain, and Coinbase Commerce tells us about it purely
10	 * by webhook. This route is therefore not a backstop here, it is the whole path.
11	 *
12	 * Signature verification is an HMAC-SHA256 of the RAW body against
13	 * `COINBASE_COMMERCE_WEBHOOK_SECRET` (lib/coinbase-commerce.ts), Coinbase
14	 * Commerce's documented method. A webhook that fails verification is rejected
15	 * with 400, never processed.
16	 *
17	 * Idempotent the same way every other rail is: `fulfilExternalPayment` claims a
18	 * `FulfilledSession` row keyed `coinbase:<chargeCode>` before doing any
19	 * provisioning, so a redelivered event (Coinbase retries on anything but a 2xx)
20	 * is always safe to re-run.
21	 */
22	export async function POST(req: NextRequest) {
23	  if (!coinbaseConfigured()) {
24	    return NextResponse.json({ error: "not configured" }, { status: 400 });
25	  }
26	  const raw = await req.text();
27	  const sig = req.headers.get("x-cc-webhook-signature");
28	
29	  const verified = await verifyCoinbaseWebhookSignature(raw, sig);
30	  if (!verified) {
31	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
32	  }
33	
34	  let event: {
35	    type?: string;
36	    data?: { code?: string; metadata?: { nxeonPendingId?: string } };
37	  };
38	  try {
39	    event = JSON.parse(raw);
40	  } catch {
41	    return NextResponse.json({ error: "invalid payload" }, { status: 400 });
42	  }
43	
44	  // `charge:confirmed` is the money-moved event (on-chain confirmation reached the
45	  // configured threshold). `charge:failed`/`charge:delayed` intentionally do
46	  // nothing here — a delayed charge may still confirm later, and a failed one
47	  // never took money, so there is nothing to fulfil or unwind.
48	  if (event.type === "charge:confirmed") {
49	    const chargeCode = event.data?.code;
50	    const pendingId = event.data?.metadata?.nxeonPendingId;
51	    if (!chargeCode || !pendingId) {
52	      console.error("[coinbase-webhook] confirmed event missing code/pendingId", event.data?.code);
53	      return NextResponse.json({ received: true });
54	    }
55	    try {
56	      const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
57	      if (!row) {
58	        console.error("[coinbase-webhook] no PendingExternalPayment for", pendingId);
59	        return NextResponse.json({ received: true });
60	      }
61	      await fulfilExternalPayment({ provider: "coinbase", externalId: chargeCode, pendingId, base: process.env.APP_URL ?? "" });
62	    } catch (e) {
63	      // Swallowed deliberately, same as the Stripe/PayPal webhooks: a non-2xx
64	      // makes Coinbase Commerce retry, and the failure is already recorded on the
65	      // FulfilledSession row and surfaced to the customer via notifyStalled.
66	      console.error("[coinbase-webhook] fulfil failed", chargeCode, e);
67	    }
68	  }
69	
70	  return NextResponse.json({ received: true });
71	}
