100	
101	  // 3. Modal submit — the owner's typed reply, OR a new ticket from /support.
102	  if (type === InteractionType.MODAL_SUBMIT) {
103	    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
