121	  // lib/discord-status-command.ts) and /support (opens the new-ticket modal
122	  // for a linked customer — lib/discord-support-command.ts).
123	  if (type === InteractionType.APPLICATION_COMMAND) {
124	    const name = (interaction.data as { name?: string } | undefined)?.name;
125	    if (name === "status") {
