104	/**
105	 * Verify a webhook really came from Coinbase Commerce: HMAC-SHA256 of the RAW
106	 * request body, keyed by the shared webhook secret, compared to the
107	 * `X-CC-Webhook-Signature` header — Coinbase Commerce's documented method. A
108	 * timing-safe comparison and a length check first (crypto.timingSafeEqual throws
109	 * on mismatched lengths rather than returning false, so a naive call would leak
110	 * timing information on the FIRST forged attempt with a wrong-length signature).
111	 * Returns false (never throws) on any missing configuration or malformed header —
112	 * an unverifiable webhook must be rejected, not treated as authentic-by-default.
113	 */
114	export async function verifyCoinbaseWebhookSignature(rawBody: string, signatureHeader: string | null): Promise<boolean> {
115	  const secret = (process.env.COINBASE_COMMERCE_WEBHOOK_SECRET ?? "").trim();
116	  if (!secret || !signatureHeader) return false;
117	  const { createHmac, timingSafeEqual } = await import("node:crypto");
118	  const expected = createHmac("sha256", secret).update(rawBody, "utf8").digest("hex");
119	  const a = Buffer.from(expected, "hex");
120	  const b = Buffer.from(signatureHeader.trim(), "hex");
121	  if (a.length !== b.length || a.length === 0) return false;
122	  return timingSafeEqual(a, b);
123	}
