98	  if (raw.length !== 32) throw new Error(`Discord public key must decode to 32 bytes, got ${raw.length}`);
99	  return createPublicKey({
100	    key: Buffer.concat([ED25519_SPKI_DER_PREFIX, raw]),
101	    format: "der",
102	    type: "spki",
