106	/**
107	 * Verify a Discord Interactions Endpoint request. Discord signs
108	 * `timestamp + rawBody` with Ed25519 and sends the signature + timestamp as
109	 * headers; this MUST be checked against the raw (pre-JSON-parse) request body
110	 * before trusting anything in it. Returns false on ANY problem (missing
111	 * headers, malformed hex, wrong-length key, bad signature, tampered body) —
112	 * never throws, so callers can treat "false" as the single "reject with 401"
113	 * signal.
114	 */
115	export function verifyDiscordSignature(args: {
116	  rawBody: string;
117	  signature: string | null | undefined;
118	  timestamp: string | null | undefined;
119	  publicKeyHex: string;
120	}): boolean {
121	  const { rawBody, signature, timestamp, publicKeyHex } = args;
122	  if (!signature || !timestamp || !publicKeyHex) return false;
123	  try {
124	    if (!/^[0-9a-f]+$/i.test(signature) || !/^[0-9a-f]+$/i.test(publicKeyHex)) return false;
125	    const key = ed25519PublicKeyFromHex(publicKeyHex);
126	    const message = Buffer.from(timestamp + rawBody, "utf8");
127	    const sig = Buffer.from(signature, "hex");
128	    return cryptoVerify(null, message, key, sig);
129	  } catch {
130	    return false;
131	  }
132	}
