8	/**
9	 * GET /api/v1/servers
10	 * Bearer-token authenticated. Returns the caller's servers.
11	 *
12	 *   Authorization: Bearer nxe_<prefix>_<random>
13	 */
14	export async function GET(req: Request) {
15	  const auth = await authenticateApiToken(req);
16	  if (!auth.ok) {
17	    return NextResponse.json({ error: auth.error }, { status: auth.status, headers: NO_STORE_HEADERS });
18	  }
19	
20	  // Enforce read scope. Legacy tokens (no scopes recorded) are READ-ONLY — they
21	  // satisfy this check and nothing that mutates. See `tokenHasScope` in
22	  // lib/api-auth.ts; a mutating endpoint must use `authorizeApiRequest`.
23	  if (!tokenHasScope(auth, "servers:read")) {
24	    return NextResponse.json(
25	      { error: "Token missing required scope: servers:read" },
26	      { status: 403, headers: NO_STORE_HEADERS }
27	    );
28	  }
29	
30	  const servers = await db.server.findMany({
31	    where: { userId: auth.user.id },
32	    orderBy: { createdAt: "desc" },
33	    select: { id: true, name: true, status: true, ipAddress: true },
34	  });
35	
36	  // Per-account inventory (names + IP addresses). The URL is identical for every
37	  // token holder, so a shared cache keyed on the URL alone would serve one
38	  // customer's server list to the next — `Authorization` is a request header and
39	  // does not vary the cache key on its own. `private` is the control that matters.
40	  return NextResponse.json(
41	    {
42	      servers: servers.map((s) => ({
43	        id: s.id,
44	        name: s.name,
45	        status: s.status,
46	        ip: s.ipAddress,
47	      })),
48	    },
49	    { headers: NO_STORE_HEADERS }
50	  );
51	}
