5	
6	/**
7	 * Live Matrix status for the sidebar tag.
8	 *
9	 *   GET /api/claude/console-status
10	 *     -> { running: number, needsAttention: number, lastEventAt: string | null }
11	 *
12	 * Session-gated (a caller only ever sees their OWN builds). Polled by the portal
13	 * Shell to drive the "running" / "update ready" tag next to the Matrix nav item.
14	 * Fails soft: any error returns a zeroed payload so the tag simply stays dark.
15	 *
16	 *   - running        = builds still in flight (planning / queued / running)
17	 *   - needsAttention = plans waiting for the owner to approve
18	 *   - lastEventAt    = most recent time a build reached a state worth surfacing
19	 *                      (finished DONE/FAILED, or a plan became AWAITING_APPROVAL);
20	 *                      the client compares it against a locally-stored "last seen"
21	 *                      to decide whether to show the "update ready" tag.
22	 */
23	export const dynamic = "force-dynamic";
24	
25	const ATTENTION_STATUSES = new Set(["AWAITING_APPROVAL", "DONE", "FAILED"]);
26	
27	export async function GET() {
28	  const user = await currentUser();
29	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
30	
31	  try {
32	    const rows = await db.claudeBuild.findMany({
33	      where: { userId: user.id },
34	      orderBy: { updatedAt: "desc" },
35	      take: 50,
36	      select: { status: true, updatedAt: true },
37	    });
38	
39	    let running = 0;
40	    let needsAttention = 0;
41	    let lastEventAt: Date | null = null;
42	    for (const r of rows) {
43	      if (r.status === "AWAITING_APPROVAL") needsAttention++;
44	      // "running" excludes AWAITING_APPROVAL — that's waiting on the user, not work in flight.
45	      else if (isBuildActive(r.status)) running++;
46	      if (ATTENTION_STATUSES.has(r.status) && (!lastEventAt || r.updatedAt > lastEventAt)) {
47	        lastEventAt = r.updatedAt;
48	      }
49	    }
50	
51	    return NextResponse.json({
52	      running,
53	      needsAttention,
54	      lastEventAt: lastEventAt ? lastEventAt.toISOString() : null,
55	    });
56	  } catch {
57	    // Fail soft — a status tag must never break the portal.
58	    return NextResponse.json({ running: 0, needsAttention: 0, lastEventAt: null });
59	  }
60	}
