2	import bcrypt from "bcryptjs";
3	import { db } from "@/lib/db";
4	import { createSession } from "@/lib/auth";
5	import { safeNext } from "@/lib/safe-next";
6	import { normalizeEmail } from "@/lib/email-normalize";
7	import { generateReferralCode, signupFreeCreditCents } from "@/lib/growth";
8	import { getSettingInt } from "@/lib/settings";
9	import {
10	  googleExchangeCode,
11	  googleFetchProfile,
12	  googleOauthConfigured,
13	  randomUrlSafe,
14	} from "@/lib/google-oauth";
15	
16	export const dynamic = "force-dynamic";
