18	const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
19	const STATE_COOKIE = "nx_google_oauth";
20	
21	type Stash = { state?: string; next?: string };
22	
23	/** Clear the one-shot state cookie on every exit path. */
24	function finish(res: NextResponse): NextResponse {
25	  res.cookies.set({ name: STATE_COOKIE, value: "", httpOnly: true, path: "/api/auth/google", maxAge: 0 });
26	  return res;
27	}
