20	/** Upload an attachment to a card. Admin only. Stored on disk so it can be read
21	 *  and acted on directly. `?cardId=` in the query. */
22	export async function POST(req: NextRequest) {
23	  try {
24	    await requireAdmin();
25	  } catch {
26	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
27	  }
28	  const cardId = req.nextUrl.searchParams.get("cardId") ?? "";
29	  const card = await db.card.findUnique({ where: { id: cardId }, select: { id: true } });
30	  if (!card) return NextResponse.json({ error: "Card not found" }, { status: 404 });
