32	  const form = await req.formData();
33	  const file = form.get("file");
34	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
35	
36	  let mime = file.type || "application/octet-stream";
37	  let kind = kindFor(mime);
38	  const cap = kind === "VIDEO" ? MAX_VIDEO : MAX_OTHER;
39	  if (file.size > cap) return NextResponse.json({ error: `File too large (max ${Math.round(cap / 1024 / 1024)} MB)` }, { status: 413 });
40	
41	  const buf = Buffer.from(await file.arrayBuffer());
42	
43	  // A file that CLAIMS to be an image is served inline by the [id] route, so it
44	  // must be a real raster image — never a scripted SVG (stored XSS in the admin
45	  // origin). Verify by byte signature and store the sniffed canonical MIME; SVG
46	  // has no signature and is not allow-listed, so it is rejected here. (Non-image
47	  // MIMEs fall through as FILE/VIDEO and are served with a download disposition.)
48	  if (kind === "IMAGE") {
49	    const sniffed = sniffImageMime(buf);
50	    if (!sniffed || mime === "image/svg+xml" || !isAllowedImageMime(mime)) {
51	      return NextResponse.json({ error: "Only PNG, JPEG, GIF, or WEBP images are allowed." }, { status: 400 });
52	    }
53	    mime = sniffed;
54	    kind = kindFor(mime);
55	  }
56	
57	  const ext = (file.name.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] ?? "").toLowerCase();
58	  const storedName = `${randomBytes(12).toString("hex")}${ext}`;
59	  const dir = join(BOARD_UPLOAD_DIR, "board", cardId);
60	  try {
61	    await fs.mkdir(dir, { recursive: true });
62	    await fs.writeFile(join(dir, storedName), buf);
63	  } catch (e) {
64	    // Almost always a permissions problem on BOARD_UPLOAD_DIR (the web process
65	    // couldn't create/write it — /opt/nxeon is root-owned, the app runs as nxeon).
66	    // Surface it instead of throwing an opaque 500 the client would swallow — that
67	    // was exactly the "upload does nothing, no preview" bug.
68	    console.error("[board] attachment write failed:", e);
69	    return NextResponse.json(
70	      { error: `Couldn't save the file (${(e as NodeJS.ErrnoException)?.code ?? "write error"}). Ensure ${BOARD_UPLOAD_DIR} is writable by the web user.` },
71	      { status: 500 },
72	    );
73	  }
74	
75	  const att = await db.cardAttachment.create({
76	    data: { cardId, filename: file.name.slice(0, 200), storedName, mime, sizeBytes: file.size, kind },
77	  });
78	  return NextResponse.json({ id: att.id, filename: att.filename, kind, mime, sizeBytes: att.sizeBytes, url: `/api/board/attachments/${att.id}` });
79	}
