1	import { NextRequest, NextResponse } from "next/server";
2	import { requireUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { cfExchangeCode, packCreds } from "@/lib/cloudflare-oauth";
5	import { parseIntent, safeNext, withResult, type CfConnectIntent } from "@/lib/cloudflare-connect-intent";
6	import { runConnectIntent } from "@/lib/cloudflare-intent-run";
7	
8	export const dynamic = "force-dynamic";
9	
10	const base = () => (process.env.APP_URL ?? "").replace(/\/$/, "");
11	
12	type Stash = { state?: string; verifier?: string; next?: string; intent?: unknown; uid?: string };
13	
14	/** Clear the one-shot OAuth cookie on every exit path. */
15	function finish(res: NextResponse): NextResponse {
16	  res.cookies.set({
17	    name: "nx_cf_oauth",
18	    value: "",
19	    httpOnly: true,
20	    path: "/api/integrations/cloudflare",
21	    maxAge: 0,
22	  });
23	  return res;
24	}
25	
26	/**
27	 * Step 2 of "Connect Cloudflare": the OAuth redirect target.
28	 *
29	 * Verifies the CSRF `state` against the httpOnly cookie, exchanges the code (with
30	 * the PKCE verifier) for credentials, stores them encrypted in the existing
31	 * `User.cloudflareTokenEnc` column, then immediately runs the action the customer
32	 * started — so they land back on their page with the DNS records already
33	 * published. No token is ever logged or put in a URL.
34	 */
35	export async function GET(req: NextRequest) {
36	  let user;
37	  try {
38	    user = await requireUser();
39	  } catch {
40	    return finish(NextResponse.redirect(`${base()}/login`));
41	  }
42	
43	  const raw = req.cookies.get("nx_cf_oauth")?.value;
44	  let stash: Stash = {};
45	  try {
46	    stash = raw ? (JSON.parse(raw) as Stash) : {};
47	  } catch {
48	    stash = {};
49	  }
50	
51	  const next = safeNext(stash.next);
52	  const fail = (msg: string) =>
53	    finish(NextResponse.redirect(`${base()}${withResult(next, { cf: "error", cfmsg: msg })}`));
54	
55	  const sp = req.nextUrl.searchParams;
56	
57	  // The customer declined on Cloudflare's consent screen (or Cloudflare errored).
58	  const oauthError = sp.get("error");
59	  if (oauthError) {
60	    return fail(
61	      oauthError === "access_denied"
62	        ? "Cloudflare connection cancelled."
63	        : `Cloudflare returned an error (${oauthError.slice(0, 60)}).`,
64	    );
65	  }
66	
67	  // CSRF: the state must match the cookie minted by /start for THIS user.
68	  const state = sp.get("state") ?? "";
69	  if (!stash.state || !stash.verifier || !state || state !== stash.state) {
70	    return fail("That Cloudflare sign-in link expired or didn't match. Please try connecting again.");
71	  }
72	  if (stash.uid && stash.uid !== user.id) {
73	    return fail("That Cloudflare sign-in was started by a different account. Please try again.");
74	  }
75	
76	  const code = sp.get("code") ?? "";
77	  if (!code) return fail("Cloudflare didn't return an authorization code. Please try connecting again.");
78	
79	  const exchanged = await cfExchangeCode({ code, codeVerifier: stash.verifier });
80	  if (!exchanged.creds) {
81	    return fail(exchanged.error ?? "Couldn't complete the Cloudflare connection. Please try again.");
82	  }
83	
84	  await db.user.update({
85	    where: { id: user.id },
86	    data: { cloudflareTokenEnc: packCreds(exchanged.creds) },
87	  });
88	  await db.auditLog
89	    .create({ data: { userId: user.id, action: "cloudflare.connect", detail: "OAuth authorised" } })
90	    .catch(() => {});
91	
92	  // "Connect → records added": finish the job they clicked from, with no extra step.
93	  const intent: CfConnectIntent =
94	    stash.intent && typeof stash.intent === "object"
95	      ? parseIntent({
96	          intent: (stash.intent as { kind?: string }).kind ?? null,
97	          id: (stash.intent as { id?: string }).id ?? null,
98	          host: (stash.intent as { host?: string }).host ?? null,
99	        })
100	      : { kind: "settings" };
101	
102	  const outcome = await runConnectIntent(intent);
103	  return finish(
104	    NextResponse.redirect(`${base()}${withResult(next, { cf: "connected", ...outcome.params })}`),
105	  );
106	}
