24	  // server action, but this is a plain GET the browser navigates to, so an
25	  // uncaught throw here is an unhandled 500, not a redirect to /login. See
26	  // app/api/integrations/cloudflare/start/route.ts for the same pattern.
27	  let me;
28	  try {
29	    me = await requireUser();
