7	/**
8	 * Per-employee (Role.EMPLOYEE) tool grants, layered ADDITIVELY on top of
9	 * lib/rbac.ts's role→area system — nothing in lib/rbac.ts changes behavior
10	 * for CUSTOMER/SUPPORT/BILLING/ADMIN. `canAccess`/`requireArea` there are
11	 * untouched; every one of their ~115 existing call sites is unaffected.
12	 *
13	 * EMPLOYEE is never listed in AREA_ROLES for any area (see lib/rbac.ts), so
14	 * an EMPLOYEE has ZERO access anywhere until a StaffGrant row exists for
15	 * them. This module is the only thing that ever reads StaffGrant, and it is
16	 * only ever consulted for the EMPLOYEE role — the fast path for every other
17	 * role is the existing, unchanged `canAccess` check with no DB hit.
18	 *
19	 * WHY A SEPARATE MODULE FROM lib/rbac.ts: keeps that file's existing,
20	 * heavily-relied-on exports byte-identical, so a diff against it proves this
21	 * feature couldn't have regressed anything already using it.
22	 *
23	 * LESSON APPLIED FROM lib/team-guard.ts's DELETION: that per-org permission
24	 * system was ripped out because it only ever filtered nav — no loader or
25	 * action actually checked it, so the "permission" was a promise the server
26	 * never kept. Every area opened to EMPLOYEE here is migrated at the ACTION
27	 * layer (see lib/actions-reddit-templates.ts, lib/actions-company-mail.ts,
28	 * lib/mail/imap.ts's resolveMailbox, lib/actions-support.ts's
29	 * requireTicketActor, lib/actions-chat.ts), not just its page.
30	 */
31	
32	export async function hasAreaAccess(user: Pick<User, "id" | "role">, area: Area): Promise<boolean> {
33	  if (canAccess(user.role, area)) return true;
34	  if (user.role !== "EMPLOYEE") return false;
35	  const grant = await db.staffGrant.findUnique({
36	    where: { userId_area: { userId: user.id, area } },
37	    select: { id: true },
38	  });
39	  return !!grant;
40	}
