49	/** Server-action guard. Throws UNAUTHORIZED/FORBIDDEN — never redirects. */
50	export async function requireGrant(area: Area): Promise<User> {
51	  const user = await realUser();
52	  if (!user) throw new Error("UNAUTHORIZED");
53	  if (user.role === "CUSTOMER") throw new Error("FORBIDDEN");
54	  if (!(await hasAreaAccess(user, area))) throw new Error("FORBIDDEN");
55	  return user;
56	}
