1	/**
2	 * Per-server / per-node bearer tokens for the nxeon-shipper live-telemetry
3	 * agent (see agent/nxeon-shipper). Unlike lib/terminal-token.ts (a 60s JWE
4	 * minted per browser session), a shipper token is a PERSISTENT machine
5	 * credential baked into cloud-init / a node's shipper config at provision
6	 * time and used indefinitely from then on — so it follows the same
7	 * hash-at-rest convention as password-reset tokens and the deploy-hook
8	 * secrets in lib/actions-account.ts, NOT the ephemeral-JWE convention:
9	 *
10	 *   - mint(): random 32-byte token, return the raw value ONCE, store only
11	 *     its SHA-256 hash (`Server.telemetryTokenHash` / `HostingNode.telemetryTokenHash`).
12	 *   - lookupByToken(): hash the presented token and look the owner up by the
13	 *     unique hash column — the same shape as PasswordResetToken lookups.
14	 *
15	 * There's no rotation UI yet (Phase 2): re-provisioning a server mints a
16	 * fresh token and overwrites the old hash, which is all we need since a
17	 * leaked shipper token only grants "post low-value connection-event rows
18	 * for this one server," not read/write access to anything else.
19	 */
20	import { randomBytes, createHash } from "node:crypto";
21	import { db } from "./db";
22	
23	export function mintTelemetryToken(): { token: string; hash: string } {
24	  const token = randomBytes(32).toString("base64url");
25	  const hash = createHash("sha256").update(token).digest("hex");
26	  return { token, hash };
27	}
28	
29	export function hashTelemetryToken(token: string): string {
30	  return createHash("sha256").update(token).digest("hex");
31	}
32	
33	/**
34	 * Mint a fresh telemetry token for a server, persist its hash, and return
35	 * the raw token to embed in that server's cloud-init config. Call this once
36	 * per (re)provision, right before buildCloudInit() so the config file the
37	 * agent boots with matches the hash we just stored.
38	 */
39	export async function mintServerTelemetryToken(serverId: string): Promise<string> {
40	  const { token, hash } = mintTelemetryToken();
41	  await db.server.update({ where: { id: serverId }, data: { telemetryTokenHash: hash } });
42	  return token;
43	}
44	
45	export async function mintHostingNodeTelemetryToken(nodeId: string): Promise<string> {
46	  const { token, hash } = mintTelemetryToken();
47	  await db.hostingNode.update({ where: { id: nodeId }, data: { telemetryTokenHash: hash } });
48	  return token;
49	}
50	
51	export type TelemetryPrincipal =
52	  | { kind: "VPS" | "GAME"; serverId: string }
53	  | { kind: "HOSTING"; nodeId: string }
54	  | { kind: "MAIL" };
55	
56	/**
57	 * Resolve a presented bearer token to the server/node it belongs to. Checked
58	 * in order: Server (VPS/GAME — nodeKind carried by the shipper's own config,
59	 * not re-derived here since a game server and a VPS look identical at this
60	 * layer), then HostingNode, then the single static MAIL_TELEMETRY_TOKEN env
61	 * secret (the mail box has no Prisma row to hang a hash off today — see
62	 * commit message for why a static shared secret is an acceptable stopgap for
63	 * one fixed, admin-controlled centralized node).
64	 */
65	export async function resolveTelemetryPrincipal(token: string, claimedNodeKind: string): Promise<TelemetryPrincipal | null> {
66	  if (!token) return null;
