13	/**
14	 * Step 1 of "Login with Google": start the OAuth Authorization Code flow.
15	 *
16	 * Mints a CSRF `state`, stashes it (with the validated return path) in a
17	 * short-lived httpOnly cookie, then 302-redirects to Google's consent screen.
18	 * Nothing sensitive rides in the URL; the callback trusts only the cookie.
19	 *
20	 * No sign-in is required to reach this route — it is the sign-in itself.
21	 */
22	export async function GET(req: NextRequest) {
23	  // If the operator hasn't added credentials yet, don't send anyone into a
24	  // broken consent flow — bounce back to the login page. (The login page also
25	  // hides the button in this state; this is the belt-and-braces server guard.)
26	  if (!googleOauthConfigured()) {
27	    return NextResponse.redirect(`${base()}/login?error=google_unavailable`);
28	  }
29	
30	  // Cheap abuse cap on starting the flow, keyed on the caller's IP.
31	  const rl = checkRateLimit(`google-oauth-start:${clientIp(req.headers)}`, {
32	    max: 20,
33	    windowMs: 60_000,
34	  });
35	  if (!rl.ok) {
36	    return NextResponse.redirect(`${base()}/login?error=google_ratelimited`);
37	  }
38	
39	  const next = safeNext(req.nextUrl.searchParams.get("next"));
40	  const state = randomUrlSafe(24);
41	
42	  const res = NextResponse.redirect(googleAuthorizeUrl({ state }));
43	  res.cookies.set({
44	    name: STATE_COOKIE,
45	    value: JSON.stringify({ state, next }),
46	    httpOnly: true,
47	    sameSite: "lax", // must survive the top-level redirect back from Google
48	    secure: base().startsWith("https://"),
49	    path: "/api/auth/google",
50	    maxAge: 600, // 10 minutes to complete consent
51	  });
52	  return res;
53	}
