72	/** True if an IP (v4 or v6) is in a blocked range. */
73	export function isBlockedIp(ip: string): boolean {
74	  const kind = net.isIP(ip);
75	  if (kind === 4) return isBlockedIpv4(ip);
76	  if (kind === 6) return isBlockedIpv6(ip);
77	  return true; // not a recognizable IP → refuse
78	}
